void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    // Assuming we have two sets of vertices 'left' and 'right' provided in the resultMap
    // For the sake of example, let's assume resultMap contains vertices labeled "left1", "left2", ..., "leftM"
    // and "right1", "right2", ..., "rightN"
    Set<V> leftVertices = new HashSet<>();
    Set<V> rightVertices = new HashSet<>();

    for (String key : resultMap.keySet()) {
        if (key.startsWith("left")) {
            leftVertices.add(resultMap.get(key));
        } else if (key.startsWith("right")) {
            rightVertices.add(resultMap.get(key));
        }
    }

    // Add edges between each vertex in the left set and each vertex in the right set
    for (V leftVertex : leftVertices) {
        for (V rightVertex : rightVertices) {
            target.addEdge(leftVertex, rightVertex);
        }
    }
}

