void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    if (resultMap == null || resultMap.size() != 2) {
        throw new IllegalArgumentException("resultMap must contain exactly two entries representing the two partitions.");
    }

    V partition1 = resultMap.get("partition1");
    V partition2 = resultMap.get("partition2");

    if (partition1 == null || partition2 == null) {
        throw new IllegalArgumentException("resultMap must contain non-null values for both partitions.");
    }

    // Assuming the graph nodes for each partition are already added to the graph
    // and resultMap holds the representative nodes for each partition.
    // We need to retrieve all nodes in each partition.
    Set<V> set1 = new HashSet<>();
    Set<V> set2 = new HashSet<>();

    for (V vertex : target.vertices()) {
        if (vertex.equals(partition1)) {
            set1.add(vertex);
        } else if (vertex.equals(partition2)) {
            set2.add(vertex);
        }
    }

    // Add edges between all nodes in set1 and set2
    for (V v1 : set1) {
        for (V v2 : set2) {
            target.addEdge(v1, v2);
        }
    }
}

