}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    // Find the first day of the month
    int firstDayOfMonth = 1;

    // Calculate the offset to the nearest dayStep
    int offset = (dayOfMonth - firstDayOfMonth) % dayStep;
    if (offset != 0) {
        dayOfMonth -= offset;
    }

    // Handle the case where dayOfMonth goes below 1
    if (dayOfMonth < 1) {
        dayOfMonth += dayStep;
        // Assuming a simple month handling without leap years for simplicity
        month--;
        if (month < 1) {
            month = 12;
            year--;
        }
    }

    return year * 10000 + month * 100 + dayOfMonth;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    int dayOfMonth = (int) (timeBucket % 100);
    int month = (int) ((timeBucket / 100) % 100);
    int year = (int) (timeBucket / 10000);

    // Calculate the new day of the month based on dayStep
    int newDayOfMonth = ((dayOfMonth - 1) / dayStep) * dayStep + 1;

    // Handle the case where the new day of the month exceeds the actual number of days in the month
    int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
        daysInMonth[1] = 29; // Leap year
    }

    if (newDayOfMonth > daysInMonth[month - 1]) {
        newDayOfMonth = daysInMonth[month - 1];
    }

    return year * 10000 + month * 100 + newDayOfMonth;
}

