List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getRawPath();
    if (path != null && !path.isEmpty()) {
        // Remove leading slash if it exists
        if (path.startsWith("/")) {
            path = path.substring(1);
        }
        // Split the path into segments
        String[] rawSegments = path.split("/");
        for (String rawSegment : rawSegments) {
            String segment = rawSegment;
            if (decode) {
                try {
                    segment = URLDecoder.decode(rawSegment, StandardCharsets.UTF_8.name());
                } catch (UnsupportedEncodingException e) {
                    throw new RuntimeException(e);
                }
            }
            segments.add(new PathSegmentImpl(segment, Collections.emptyList()));
        }
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return pathSegments;
    }
    // If the path is absolute, skip the leading '/'
    int start = path.startsWith("/") ? 1 : 0;
    String[] segments = path.substring(start).split("/");
    for (String segment : segments) {
        String processedSegment = decode ? decodeSegment(segment) : segment;
        pathSegments.add(new PathSegmentImpl(processedSegment));
    }
    return pathSegments;
}

