public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    int b;
    do {
        if (shift >= 64) {
            throw new IOException("Invalid varint64");
        }
        b = readByte();
        result |= (long)(b & 0x7F) << shift;
        shift += 7;
    } while ((b & 0x80) != 0);
    return result;
}

