private void pop(final String descriptor){
    if (descriptor.indexOf('(') != -1) { // Check if it's a method descriptor
        int end = descriptor.indexOf(')');
        String args = descriptor.substring(1, end);
        int arrayDim = 0;
        for (int i = args.length() - 1; i >= 0; i--) {
            char c = args.charAt(i);
            if (c == '[') {
                arrayDim++;
            } else {
                if (arrayDim > 0) {
                    arrayDim = 0;
                    // Popping array type
                    popType("Ljava/lang/Object;"); // Assuming all arrays are of Object type for simplicity
                } else if (c == 'B' || c == 'C' || c == 'D' || c == 'F' || c == 'I' || c == 'J' || c == 'S' || c == 'Z') {
                    // Popping primitive type
                    popType(String.valueOf(c));
                } else if (c == 'L') {
                    // Popping object type
                    StringBuilder className = new StringBuilder();
                    className.append('L');
                    while (args.charAt(i) != ';') {
                        className.append(args.charAt(i));
                        i--;
                    }
                    className.append(';');
                    popType(className.reverse().toString());
                }
            }
        }
    } else {
        // It's a field descriptor, pop the corresponding type
        popType(descriptor);
    }
}

void pop(final String descriptor) {
    int index = descriptor.indexOf('(');
    if (index != -1) {
        // It's a method descriptor, extract the argument types
        String arguments = descriptor.substring(index + 1, descriptor.indexOf(')'));
        while (!arguments.isEmpty()) {
            char typeChar = arguments.charAt(0);
            switch (typeChar) {
                case 'B':
                case 'C':
                case 'F':
                case 'I':
                case 'S':
                case 'Z':
                    // These are all single-slot types
                    arguments = arguments.substring(1);
                    break;
                case 'D':
                case 'J':
                    // These are double-slot types
                    arguments = arguments.substring(1);
                    break;
                case 'L':
                case '[':
                    // These are reference types, find the end of the type signature
                    int end = arguments.indexOf(';', 1);
                    if (end == -1) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    arguments = arguments.substring(end + 1);
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            // Pop one abstract type from the output frame stack
            // Assuming there's a method popType() to pop an abstract type from the stack
            popType();
        }
    } else {
        // It's a type descriptor, pop a single type
        popType();
    }
}

private void pop(final String descriptor){
    // Assuming a method to parse the descriptor and determine the number of types to pop
    int numTypesToPop = getTypeCountFromDescriptor(descriptor);
    for (int i = 0; i < numTypesToPop; i++) {
        outputFrameStack.pop();
    }
}

private void pop(final String descriptor){
    int index = 0;
    if (descriptor.charAt(0) == '(') {
        while (descriptor.charAt(index) != ')') {
            if (descriptor.charAt(index) == '[') {
                while (descriptor.charAt(index) == '[') {
                    index++;
                }
                if (descriptor.charAt(index) == 'L') {
                    while (descriptor.charAt(index) != ';') {
                        index++;
                    }
                }
            } else if (descriptor.charAt(index) == 'L') {
                while (descriptor.charAt(index) != ';') {
                    index++;
                }
            }
            index++;
        }
        index++; // skip ')'
    }
    while (index < descriptor.length()) {
        if (descriptor.charAt(index) == '[') {
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            if (descriptor.charAt(index) == 'L') {
