String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder output = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char currentChar = str.charAt(i);
        if (currentChar == '\\') {
            i++;
            if (i >= length) {
                throw new Exception("Invalid escape sequence");
            }
            char nextChar = str.charAt(i);
            switch (nextChar) {
                case 'b':
                    output.append('\b');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'n':
                    output.append('\n');
                    break;
                case 'f':
                    output.append('\f');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case '\"':
                    output.append('\"');
                    break;
                case '\'':
                    output.append('\'');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= length) {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    int codePoint = Integer.parseInt(str.substring(i + 1, i + 5), 16);
                    output.append((char) codePoint);
                    i += 4;
                    break;
                default:
                    throw new Exception("Invalid escape sequence");
            }
        } else {
            output.append(currentChar);
        }
    }
    return output.toString();
}

