protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    DefaultGraphPath<V, E> path = new DefaultGraphPath<>();
    if (edgeList.isEmpty()) {
        return path;
    }

    // Assuming the graph is connected and the tour is a valid cycle
    E firstEdge = edgeList.get(0);
    V startVertex = graph.getEdgeSource(firstEdge);
    V currentVertex = startVertex;

    path.addVertex(startVertex);
    for (E edge : edgeList) {
        path.addEdge(edge);
        currentVertex = Graphs.getOppositeVertex(graph, edge, currentVertex);
        path.addVertex(currentVertex);
    }

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    Set<E> visitedEdges = new HashSet<>();
    V currentVertex = startVertex;

    while (vertexList.size() <= graph.vertexSet().size()) {
        for (E edge : edgeList) {
            if (!visitedEdges.contains(edge) && (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex))) {
                visitedEdges.add(edge);
                currentVertex = graph.getEdgeSource(edge).equals(currentVertex) ? graph.getEdgeTarget(edge) : graph.getEdgeSource(edge);
                vertexList.add(currentVertex);
                break;
            }
        }
    }

    return new SimpleGraphPath<>(graph, vertexList, edgeList);
}

GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = edgeList.isEmpty() ? null : graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();
    V currentVertex = startVertex;

    while (currentVertex != null && !visitedEdges.containsAll(tour)) {
        vertexList.add(currentVertex);
        E nextEdge = null;
        for (E edge : tour) {
            if (!visitedEdges.contains(edge) && (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex))) {
                nextEdge = edge;
                break;
            }
        }
        if (nextEdge != null) {
            visitedEdges.add(nextEdge);
            currentVertex = graph.getEdgeSource(nextEdge).equals(currentVertex) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        } else {
            currentVertex = null; // In case of isolated vertex or wrong input
        }
    }
    vertexList.add(vertexList.get(0)); // Close the tour

    return new GraphPathImpl<>(graph, startVertex, vertexList, edgeList, 0.0);
}

GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();

    if (edgeList.isEmpty()) {
        return new GraphPathImpl<>(graph, null, vertexList, 0.0);
    }

    V startVertex = graph.getEdgeSource(edgeList.get(0));
    vertexList.add(startVertex);

    while (!edgeList.isEmpty()) {
        E currentEdge = null;
        for (E edge : edgeList) {
            if (graph.getEdgeSource(edge).equals(startVertex) || graph.getEdgeTarget(edge).equals(startVertex)) {
                currentEdge = edge;
                break;
            }
        }

        if (currentEdge == null) {
            break; // In case the graph is not fully connected or the set does not form a valid tour
        }

        vertexList.add(graph.getEdgeTarget(currentEdge).equals(startVertex) ? graph.getEdgeSource(currentEdge) : graph.getEdgeTarget(currentEdge));
        startVertex = vertexList.get(vertexList.size() - 1);
        edgeList.remove(currentEdge);
    }

    double weight = tour.stream().mapToDouble(graph::getEdgeWeight).sum();
    return new GraphPathImpl<>(graph, vertexList.get(0), vertexList, weight);
}

