String applyRelativePath(String path, String relativePath) {
    // Normalize the path by removing trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Use a list to build the final path
    List<String> finalPathComponents = new ArrayList<>(Arrays.asList(pathComponents));

    // Process each component of the relative path
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            // Move up one directory if possible
            if (finalPathComponents.size() > 0) {
                finalPathComponents.remove(finalPathComponents.size() - 1);
            }
        } else if (!component.equals(".")) {
            // Add the component to the path
            finalPathComponents.add(component);
        }
    }

    // Join the components back into a single string
    return String.join("/", finalPathComponents);
}

public static String applyRelativePath(String path, String relativePath) {
